                                        "center",
                                        "right"
                                    ]
                                },
                                "caption": {
                                    "type": "string"
                                }
                            },
                            "required": [
                                "file_id"
                            ]
                        }
                    },
                    "required": [
                        "image"
                    ]
                }
            ]
        },
